pub fn weighted_decay_cdf(parts: &[(f64, f64)], x: f64) -> Option<f64> {
    if parts.is_empty() || !x.is_finite() { return None; }
    let mut weight_sum = 0.0;
    for &(weight, rate) in parts {
        if !weight.is_finite() || !rate.is_finite() || weight < 0.0 || rate <= 0.0 { return None; }
        weight_sum += weight;
    }
    if weight_sum == 0.0 || !weight_sum.is_finite() { return None; }
    if x <= 0.0 { return Some(0.0); }
    let value = parts.iter().map(|&(weight, rate)| weight * (-rate * x).exp()).sum::<f64>() / weight_sum;
    Some(value.clamp(0.0, 1.0))
}

pub fn interval_cdf(low: f64, high: f64, x: f64) -> Option<f64> {
    if !low.is_finite() || !high.is_finite() || !x.is_finite() || low >= high { return None; }
    Some(if x <= low { 0.0 } else if x >= high { 1.0 } else { (x - low) / (high - low) })
}
