#[path = "solution.rs"]
mod solution;

use solution::{interval_cdf, weighted_decay_cdf};

fn close(actual: f64, expected: f64, tolerance: f64) {
    assert!((actual - expected).abs() <= tolerance, "actual={actual}, expected={expected}");
}

#[test]
fn weighted_decay_uses_one_minus_exponential_decay() {
    let parts = [(1.0, 1.0)];
    close(weighted_decay_cdf(&parts, 1.0).unwrap(), 1.0 - (-1.0f64).exp(), 1e-14);
    close(weighted_decay_cdf(&parts, 2.0).unwrap(), 1.0 - (-2.0f64).exp(), 1e-14);
}

#[test]
fn weighted_decay_normalizes_weights_and_is_order_stable() {
    let a = [(1.0, 0.5), (3.0, 2.0), (2.0, 1.25)];
    let b = [(2.0, 1.25), (1.0, 0.5), (3.0, 2.0)];
    let expected = (1.0 * (1.0 - (-0.5f64).exp())
        + 3.0 * (1.0 - (-2.0f64).exp())
        + 2.0 * (1.0 - (-1.25f64).exp())) / 6.0;
    let va = weighted_decay_cdf(&a, 1.0).unwrap();
    let vb = weighted_decay_cdf(&b, 1.0).unwrap();
    close(va, expected, 1e-14);
    close(vb, expected, 1e-14);
    close(va, vb, 1e-14);
}

#[test]
fn weighted_decay_handles_boundaries_and_zero_weight_components() {
    let parts = [(0.0, 100.0), (2.0, 0.25)];
    assert_eq!(weighted_decay_cdf(&parts, 0.0), Some(0.0));
    assert_eq!(weighted_decay_cdf(&parts, -10.0), Some(0.0));
    let value = weighted_decay_cdf(&parts, 1.0e300).unwrap();
    assert!((0.0..=1.0).contains(&value));
    close(value, 1.0, 1e-15);
}

#[test]
fn weighted_decay_rejects_invalid_inputs() {
    assert_eq!(weighted_decay_cdf(&[], 1.0), None);
    assert_eq!(weighted_decay_cdf(&[(0.0, 1.0)], 1.0), None);
    for x in [f64::NAN, f64::INFINITY, f64::NEG_INFINITY] {
        assert_eq!(weighted_decay_cdf(&[(1.0, 1.0)], x), None);
    }
    for parts in [
        vec![(f64::NAN, 1.0)],
        vec![(f64::INFINITY, 1.0)],
        vec![(-1.0, 1.0)],
        vec![(1.0, 0.0)],
        vec![(1.0, -1.0)],
        vec![(1.0, f64::INFINITY)],
    ] {
        assert_eq!(weighted_decay_cdf(&parts, 1.0), None);
    }
}

#[test]
fn weighted_decay_does_not_mutate_parts() {
    let parts = [(2.0, 0.5), (4.0, 1.5)];
    let original = parts;
    let _ = weighted_decay_cdf(&parts, 3.0);
    assert_eq!(parts, original);
}

#[test]
fn interval_cdf_has_closed_boundaries_and_linear_interior() {
    assert_eq!(interval_cdf(2.0, 6.0, 1.0), Some(0.0));
    assert_eq!(interval_cdf(2.0, 6.0, 2.0), Some(0.0));
    assert_eq!(interval_cdf(2.0, 6.0, 4.0), Some(0.5));
    assert_eq!(interval_cdf(2.0, 6.0, 6.0), Some(1.0));
    assert_eq!(interval_cdf(2.0, 6.0, 7.0), Some(1.0));
}

#[test]
fn interval_cdf_rejects_nonfinite_or_invalid_intervals() {
    assert_eq!(interval_cdf(1.0, 1.0, 1.0), None);
    assert_eq!(interval_cdf(2.0, 1.0, 1.5), None);
    assert_eq!(interval_cdf(f64::NAN, 2.0, 1.0), None);
    assert_eq!(interval_cdf(0.0, f64::INFINITY, 1.0), None);
    assert_eq!(interval_cdf(0.0, 2.0, f64::NEG_INFINITY), None);
}

